export const PLAN_FEATURES = {
  free:       { emailIntegrations: false, abTesting: false, export: false, customBranding: false, apiAccess: false },
  starter:    { emailIntegrations: true,  abTesting: false, export: false, customBranding: true,  apiAccess: false },
  pro:        { emailIntegrations: true,  abTesting: true,  export: true,  customBranding: true,  apiAccess: false },
  enterprise: { emailIntegrations: true,  abTesting: true,  export: true,  customBranding: true,  apiAccess: true  },
} as const;

export type PlanId = keyof typeof PLAN_LIMITS;
```

## Canonical: Subscription Model

```prisma
// NOT BillingPlan — NOT billing_plans — it is Subscription
model Subscription {
  id                    String    @id @default(cuid())
  shop                  String    @unique     // NOT shopId
  planId                String    @default("free")  // free | starter | pro | enterprise
  billingInterval       String    @default("monthly")
  shopifySubscriptionId String?
  status                String    @default("active")
  trialEndsAt           DateTime?
  currentPeriodEnd      DateTime?
  quizLimit             Int       @default(1)
  responseLimit         Int       @default(100)
  createdAt             DateTime  @default(now())
  updatedAt             DateTime  @updatedAt
}
```

## Implementation Steps

### Step 1: shopify.server.ts Billing Config

```typescript
// app/shopify.server.ts — add billing config
billing: {
  starter: {
    amount: 9.99,
    currencyCode: "USD",
    interval: BillingInterval.Every30Days,
  },
  pro: {
    amount: 29.99,
    currencyCode: "USD",
    interval: BillingInterval.Every30Days,
  },
  enterprise: {
    amount: 79.99,
    currencyCode: "USD",
    interval: BillingInterval.Every30Days,
  },
}
```

### Step 2: Billing Service (`app/services/billing.server.ts`)

```typescript
import db from "~/db.server";
import type { PlanId } from "~/utils/constants";
import { PLAN_LIMITS, PLAN_FEATURES } from "~/utils/constants";

export async function getSubscription(shop: string) {
  return db.subscription.upsert({
    where: { shop },
    create: { shop, planId: "free", quizLimit: 1, responseLimit: 100 },
    update: {},
  });
}

export async function requirePlan(shop: string, feature: keyof typeof PLAN_FEATURES.free) {
  const sub = await getSubscription(shop);
  const planId = sub.planId as PlanId;
  if (!PLAN_FEATURES[planId]?.[feature]) {
    throw new Error(`Upgrade required: ${feature} needs Starter plan or higher`);
  }
}

export async function checkQuizLimit(shop: string): Promise<boolean> {
  const sub = await getSubscription(shop);
  const planId = sub.planId as PlanId;
  const limit = PLAN_LIMITS[planId].quizLimit;
  if (limit === Infinity) return true;
  const count = await db.quiz.count({ where: { shop, status: { not: "archived" } } });
  return count < limit;
}
```

### Step 3: Pricing Page (`app/routes/app.billing.tsx`)

```tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useNavigation, useSubmit } from "react-router";  // NOT @remix-run/react
import { useAppBridge } from "@shopify/app-bridge-react";
import { Page, Layout, Card, Grid, BlockStack, InlineStack, Text, Badge, Button,
         Banner, List, Divider } from "@shopify/polaris";
import { authenticate } from "~/shopify.server";
import { getSubscription } from "~/services/billing.server";
import { PLAN_LIMITS, PLAN_FEATURES } from "~/utils/constants";

const PLANS = [
  { id: "free", name: "Free", monthly: 0, annual: 0,
    features: ["1 quiz", "100 responses/mo", "Basic analytics"] },
  { id: "starter", name: "Starter", monthly: 9.99, annual: 7.99,
    features: ["5 quizzes", "1,000 responses/mo", "Email integrations", "Remove branding"] },
  { id: "pro", name: "Pro", monthly: 29.99, annual: 23.99,
    features: ["Unlimited quizzes", "10,000 responses/mo", "A/B testing", "CSV export", "Full analytics"] },
  { id: "enterprise", name: "Enterprise", monthly: 79.99, annual: 63.99,
    features: ["Everything in Pro", "Unlimited responses", "API access", "Priority support"] },
];

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const subscription = await getSubscription(session.shop);
  return json({ subscription });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session, billing } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const planId = formData.get("planId") as string;

  try {
    if (intent === "upgrade" && planId !== "free") {
      await billing.request({
        plan: planId,
        isTest: process.env.NODE_ENV !== "production",
        returnUrl: `${process.env.HOST}/app/billing`,
      });
    }
    return json({ success: true, message: `Upgraded to ${planId}` });
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Billing error" }, { status: 500 });
  }
}

export default function BillingPage() {
  const { subscription } = useLoaderData<typeof loader>();
  const navigation = useNavigation();
  const submit = useSubmit();
  const shopify = useAppBridge();
  const [billingInterval, setBillingInterval] = useState<"monthly" | "annual">("monthly");

  const handleUpgrade = (planId: string) => {
    submit({ intent: "upgrade", planId }, { method: "POST" });
    shopify.toast.show("Redirecting to billing...", { duration: 3000 });
  };

  return (
    <Page title="Billing & Plans">
      <Layout>
        <Layout.Section>
          <Banner tone="info">
            <p>Current plan: <strong>{subscription.planId}</strong></p>
          </Banner>
        </Layout.Section>
        <Layout.Section>
          <InlineStack gap="400" align="center">
            <Button
              variant={billingInterval === "monthly" ? "primary" : "plain"}
              onClick={() => setBillingInterval("monthly")}
            >Monthly</Button>
            <Button
              variant={billingInterval === "annual" ? "primary" : "plain"}
              onClick={() => setBillingInterval("annual")}
            >Annual (save 20%)</Button>
          </InlineStack>
        </Layout.Section>
        <Layout.Section>
          <Grid>
            {PLANS.map((plan) => {
              const isCurrent = subscription.planId === plan.id;
              const price = billingInterval === "annual" ? plan.annual : plan.monthly;
              return (
                <Grid.Cell key={plan.id} columnSpan={{ xs: 6, sm: 6, md: 3, lg: 3 }}>
                  <Card background={plan.id === "pro" ? "bg-surface-success" : undefined}>
                    <BlockStack gap="400">
                      <InlineStack align="space-between">
                        <Text variant="headingLg" as="h3">{plan.name}</Text>
                        {isCurrent && <Badge tone="success">Current plan</Badge>}
                      </InlineStack>
                      <Text variant="heading2xl" fontWeight="bold" as="p">
                        {price === 0 ? "Free" : `$${price}/mo`}
                      </Text>
                      <List>
                        {plan.features.map((f) => <List.Item key={f}>{f}</List.Item>)}
                      </List>
                      {!isCurrent && plan.id !== "free" && (
                        <Button
                          variant="primary"
                          fullWidth
                          onClick={() => handleUpgrade(plan.id)}
                          loading={navigation.state !== "idle"}
                        >
                          Upgrade to {plan.name}
                        </Button>
                      )}
                      {isCurrent && (
                        <Text tone="subdued" as="p">Your current plan</Text>
                      )}
                    </BlockStack>
                  </Card>
                </Grid.Cell>
              );
            })}
          </Grid>
        </Layout.Section>
      </Layout>
    </Page>
  );
}
```

### Step 4: Plan Gating in Loaders/Actions

