                  ]}
                  value={config.triggerType}
                />
                <Button
                  variant="primary"
                  submit
                  loading={navigation.state !== "idle"}
                >
                  Save settings
                </Button>
              </FormLayout>
            </Form>
          </Card>
        </Layout.AnnotatedSection>
      </Layout>
    </Page>
  );
}
