Add an integration to QuizSnap: $ARGUMENTS

## Pre-Flight (Read First)
1. Read `CLAUDE.md` Section 4 — `EmailIntegration` canonical model
2. Read `CLAUDE.md` Section 7 — plan gating (email integrations: Starter+)
3. Read `CLAUDE.md` Law 13 — plan gating on premium features

## Agent Routing

| Integration Type        | Primary Agent          | Support Agents                      |
|-------------------------|------------------------|-------------------------------------|
| Klaviyo                 | `klaviyo-specialist`   | `email-integration`                 |
| Mailchimp               | `email-integration`    | `api-builder`                       |
| Omnisend                | `email-integration`    | `api-builder`                       |
| Shopify Flow            | `shopify-flow`         | `webhook-handler`                   |
| Custom webhook          | `webhook-handler`      | `api-builder`                       |
| Google Analytics        | `analytics-builder`    | `storefront-builder`                |
| Meta Pixel              | `analytics-builder`    | `storefront-builder`                |

## Canonical: EmailIntegration Model

```prisma
model EmailIntegration {
  id        String   @id @default(cuid())
  shop      String                            // NOT shopId
  provider  String                            // klaviyo | mailchimp | omnisend | custom-webhook
  apiKey    String
  listId    String?
  settings  String   @default("{}")           // JSON: provider-specific config
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([shop, provider])
  @@index([shop])
}
```

## Implementation Steps

### Step 1: Plan Gate Check (Law 13)

```typescript
// app/services/billing.server.ts
// Email integrations require Starter plan minimum
export async function requirePlan(shop: string, feature: "emailIntegrations") {
  const sub = await getSubscription(shop);
  if (!PLAN_FEATURES[sub.planId as PlanId]?.emailIntegrations) {
    throw json({ error: "Email integrations require Starter plan", planRequired: "starter" }, { status: 403 });
  }
}

// In loader:
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  await requirePlan(session.shop, "emailIntegrations");
  // ...
}
```

### Step 2: Integration Settings UI (Polaris v13)

```tsx
// app/routes/app.integrations.tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useNavigation, Form } from "react-router";  // NOT @remix-run/react
import { useAppBridge } from "@shopify/app-bridge-react";
import { Page, Layout, Card, FormLayout, TextField, Button, Badge,
         BlockStack, InlineStack, Text, Banner, Divider } from "@shopify/polaris";
import { authenticate } from "~/shopify.server";
import db from "~/db.server";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const integrations = await db.emailIntegration.findMany({
    where: { shop: session.shop },  // NOT shopId
  });
  return json({ integrations });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "save": {
        const provider = formData.get("provider") as string;
        const apiKey = formData.get("apiKey") as string;
        const listId = formData.get("listId") as string | null;
        await db.emailIntegration.upsert({
          where: { shop_provider: { shop, provider } },
          create: { shop, provider, apiKey, listId: listId ?? undefined, isActive: true },
          update: { apiKey, listId: listId ?? undefined, isActive: true },
        });
        return json({ success: true, message: `${provider} connected` });
      }
      case "disconnect": {
        const provider = formData.get("provider") as string;
        await db.emailIntegration.updateMany({
          where: { shop, provider },
          data: { isActive: false },
        });
        return json({ success: true, message: `${provider} disconnected` });
      }
      case "test": {
        const provider = formData.get("provider") as string;
        const integration = await db.emailIntegration.findUnique({
          where: { shop_provider: { shop, provider } },
        });
        if (!integration || !integration.isActive) {
          return json({ error: "Integration not configured" }, { status: 400 });
        }
        // Test the connection (provider-specific)
        return json({ success: true, message: "Connection verified!" });
      }
      default:
        return json({ error: "Unknown intent" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Error" }, { status: 500 });
  }
}

export default function IntegrationsPage() {
  const { integrations } = useLoaderData<typeof loader>();
  const navigation = useNavigation();
  const shopify = useAppBridge();
  const actionData = useActionData<typeof action>();

  useEffect(() => {
    if (actionData?.success) shopify.toast.show(actionData.message, { duration: 3000 });
    if (actionData?.error) shopify.toast.show(actionData.error, { isError: true });
  }, [actionData]);

  const PROVIDERS = [
    { id: "klaviyo", name: "Klaviyo", description: "Sync subscribers to Klaviyo lists" },
    { id: "mailchimp", name: "Mailchimp", description: "Add subscribers to Mailchimp audiences" },
    { id: "omnisend", name: "Omnisend", description: "Sync contacts to Omnisend" },
  ];

  return (
    <Page title="Email Integrations">
      <Layout>
        {PROVIDERS.map((provider) => {
          const integration = integrations.find((i) => i.provider === provider.id);
          const isConnected = integration?.isActive;
          return (
            <Layout.AnnotatedSection
              key={provider.id}
              title={provider.name}
              description={provider.description}
            >
              <Card>
                <BlockStack gap="400">
                  <InlineStack align="space-between">
                    <Text variant="headingMd" as="h3">{provider.name}</Text>
                    <Badge tone={isConnected ? "success" : "subdued"}>
                      {isConnected ? "Connected" : "Not connected"}
                    </Badge>
                  </InlineStack>
                  <Form method="POST">
                    <input type="hidden" name="provider" value={provider.id} />
                    <FormLayout>
                      <TextField
                        label="API Key"
                        name="apiKey"
                        type="password"
                        defaultValue={integration?.apiKey ? "••••••••" : ""}
                        autoComplete="off"
                      />
                      <TextField
                        label="List / Audience ID"
                        name="listId"
                        defaultValue={integration?.listId ?? ""}
                        autoComplete="off"
                      />
                      <InlineStack gap="200">
                        <Button
                          variant="primary"
                          name="intent"
