  const { session } = await authenticate.admin(request);
  const integrations = await db.emailIntegration.findMany({
    where: { shop: session.shop },  // NOT shopId
  });
  return json({ integrations });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "save": {
        const provider = formData.get("provider") as string;
        const apiKey = formData.get("apiKey") as string;
        const listId = formData.get("listId") as string | null;
        await db.emailIntegration.upsert({
          where: { shop_provider: { shop, provider } },
          create: { shop, provider, apiKey, listId: listId ?? undefined, isActive: true },
          update: { apiKey, listId: listId ?? undefined, isActive: true },
        });
        return json({ success: true, message: `${provider} connected` });
      }
      case "disconnect": {
        const provider = formData.get("provider") as string;
        await db.emailIntegration.updateMany({
          where: { shop, provider },
          data: { isActive: false },
        });
        return json({ success: true, message: `${provider} disconnected` });
      }
      case "test": {
        const provider = formData.get("provider") as string;
        const integration = await db.emailIntegration.findUnique({
          where: { shop_provider: { shop, provider } },
        });
        if (!integration || !integration.isActive) {
          return json({ error: "Integration not configured" }, { status: 400 });
        }
        // Test the connection (provider-specific)
        return json({ success: true, message: "Connection verified!" });
      }
      default:
        return json({ error: "Unknown intent" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Error" }, { status: 500 });
  }
}

