  will-change: transform;
}

.quiz-card.slide-in {
  transform: translateX(100%);
  opacity: 0;
}

.quiz-card.active {
  transform: translateX(0);
  opacity: 1;
}
```

## API Response Optimizations

### Cache Headers for Stable Data

```typescript
// Public quiz data doesn't change often — cache for 60s
return json(quizData, {
  headers: {
    ...CORS_HEADERS,
    "Cache-Control": "public, max-age=60, stale-while-revalidate=300",
  },
});
```

## Measurement Commands

```bash
# Check query count and timing (add to loader temporarily)
console.time("loader");
const result = await db.quiz.findMany({ where: { shop } });
console.timeEnd("loader");

# Bundle analysis
npm run build
# Check: public/build/ for bundle sizes

# Type check (catches unnecessary any casts that slow type inference)
npm run typecheck
```

