## Test Patterns

### Mock Prisma Client

```typescript
// test setup
import { vi } from "vitest";

const mockDb = {
  quiz: {
    findMany: vi.fn(),
    findFirst: vi.fn(),
    findUnique: vi.fn(),
    create: vi.fn(),
    update: vi.fn(),
    delete: vi.fn(),
    deleteMany: vi.fn(),
    count: vi.fn(),
  },
  question: {
    findMany: vi.fn(),
    create: vi.fn(),
    updateMany: vi.fn(),
  },
  subscription: {
    findUnique: vi.fn(),
    upsert: vi.fn(),
  },
};

vi.mock("~/db.server", () => ({ default: mockDb }));
```

### Mock Shopify Auth (ALWAYS use `shop` not `shopId`)

```typescript
const mockSession = {
  shop: "test-shop.myshopify.com",  // NOT shopId
  accessToken: "shpat_test123",
};

vi.mock("~/shopify.server", () => ({
  authenticate: {
    admin: vi.fn().mockResolvedValue({
      session: mockSession,
      admin: { graphql: vi.fn() },
    }),
    webhook: vi.fn().mockResolvedValue({
      shop: "test-shop.myshopify.com",
      topic: "APP_UNINSTALLED",
    }),
  },
}));
```

### Testing Loaders

```typescript
import { describe, it, expect, beforeEach, vi } from "vitest";
import { loader } from "~/routes/app.quizzes";

describe("app.quizzes loader", () => {
  beforeEach(() => {
    mockDb.quiz.findMany.mockResolvedValue([
      { id: "quiz1", shop: "test-shop.myshopify.com", title: "My Quiz",
        status: "active", completions: 42, _count: { questions: 5 } },
    ]);
  });

  it("returns quizzes for authenticated shop", async () => {
    const request = new Request("http://localhost/app/quizzes");
    const response = await loader({ request, params: {}, context: {} });
    const data = await response.json();

    expect(data.quizzes).toHaveLength(1);
    expect(data.quizzes[0].title).toBe("My Quiz");
    // Verify shop-scoped query was called
    expect(mockDb.quiz.findMany).toHaveBeenCalledWith(
      expect.objectContaining({ where: { shop: "test-shop.myshopify.com" } })
    );
  });

  it("redirects without auth", async () => {
    vi.mocked(authenticate.admin).mockRejectedValueOnce(new Response(null, { status: 302 }));
    const request = new Request("http://localhost/app/quizzes");
    await expect(loader({ request, params: {}, context: {} })).rejects.toBeInstanceOf(Response);
  });
});
```

### Testing Actions

```typescript
import { action } from "~/routes/app.quizzes";

describe("app.quizzes action", () => {
  it("deletes quiz owned by shop", async () => {
    mockDb.quiz.deleteMany.mockResolvedValue({ count: 1 });

    const formData = new FormData();
    formData.set("intent", "delete");
    formData.set("id", "quiz1");

    const request = new Request("http://localhost/app/quizzes", {
      method: "POST",
      body: formData,
    });
    const response = await action({ request, params: {}, context: {} });
    const data = await response.json();

    expect(data.success).toBe(true);
    // Verify it scoped delete to session.shop
    expect(mockDb.quiz.deleteMany).toHaveBeenCalledWith({
      where: { id: "quiz1", shop: "test-shop.myshopify.com" },
    });
  });

  it("rejects unknown intent", async () => {
    const formData = new FormData();
    formData.set("intent", "evil_action");

    const request = new Request("http://localhost/app/quizzes", {
      method: "POST",
      body: formData,
    });
    const response = await action({ request, params: {}, context: {} });
    expect(response.status).toBe(400);
  });
});
```

### Testing Scoring Engine

```typescript
// app/utils/scoring.test.ts
import { describe, it, expect } from "vitest";
import { calculateScore, matchResultPage } from "./scoring";

describe("calculateScore", () => {
  it("sums answer scores correctly", () => {
    const answers = [
      { answerId: "a1", score: 10 },
      { answerId: "a2", score: 20 },
    ];
    expect(calculateScore(answers)).toBe(30);
  });

  it("returns 0 for empty answers", () => {
    expect(calculateScore([])).toBe(0);
  });
});

describe("matchResultPage", () => {
  const resultPages = [
    { id: "r1", type: "score-range", minScore: 0, maxScore: 30, matchTags: "[]", position: 0 },
    { id: "r2", type: "score-range", minScore: 31, maxScore: 100, matchTags: "[]", position: 1 },
  ];

  it("matches correct score range", () => {
    expect(matchResultPage(25, [], resultPages)).toBe("r1");
    expect(matchResultPage(50, [], resultPages)).toBe("r2");
  });

  it("matches tag-based results", () => {
    const tagResultPages = [
      { id: "r3", type: "tag-match", minScore: null, maxScore: null,
        matchTags: '["moisturizing", "gentle"]', position: 0 },
    ];
    const answerTags = ["moisturizing", "spf"];
    expect(matchResultPage(0, answerTags, tagResultPages)).toBe("r3");
  });
});
```

### Testing Public API with CORS

```typescript
import { loader } from "~/routes/api.quiz.$slug";

describe("api.quiz.$slug loader", () => {
  it("includes CORS headers on success", async () => {
    mockDb.quiz.findUnique.mockResolvedValue({
      id: "quiz1", shop: "test.myshopify.com", slug: "my-quiz", status: "active",
      questions: [], resultPages: [], settings: "{}", styling: "{}",
    });

    const request = new Request("http://localhost/api/quiz/my-quiz?shop=test.myshopify.com");
    const response = await loader({ request, params: { slug: "my-quiz" }, context: {} });

    expect(response.headers.get("Access-Control-Allow-Origin")).toBe("*");
    expect(response.status).toBe(200);
  });

  it("includes CORS headers on 404", async () => {
    mockDb.quiz.findUnique.mockResolvedValue(null);

    const request = new Request("http://localhost/api/quiz/bad-slug?shop=test.myshopify.com");
    const response = await loader({ request, params: { slug: "bad-slug" }, context: {} });

    expect(response.headers.get("Access-Control-Allow-Origin")).toBe("*");
    expect(response.status).toBe(404);
  });

  it("handles OPTIONS preflight", async () => {
    const request = new Request("http://localhost/api/quiz/slug?shop=test.myshopify.com", {
      method: "OPTIONS",
    });
    const response = await loader({ request, params: { slug: "slug" }, context: {} });
    expect(response.status).toBe(204);
  });
});
