Scaffold a new route or component for QuizSnap: $ARGUMENTS

## Pre-Flight (Read First)
1. Read `CLAUDE.md` Section 3 — folder structure and file locations
2. Read `CLAUDE.md` Section 8 — production code patterns (use as template)
3. Find the closest existing file to use as a pattern — READ it before scaffolding

## Agent Routing

| Scaffold Type           | Primary Agent       | Uses Pattern From                   |
|-------------------------|---------------------|-------------------------------------|
| Admin route             | `admin-builder`     | `CLAUDE.md` Section 8.1             |
| Public API route        | `api-builder`       | `CLAUDE.md` Section 8.2             |
| Webhook route           | `webhook-handler`   | `CLAUDE.md` Section 8               |
| Polaris component       | `admin-builder`     | Existing `app/components/`          |
| Service file            | `prisma-queries`    | `CLAUDE.md` Section 8.3            |
| Prisma model            | `prisma-schema`     | `CLAUDE.md` Section 4               |

## Admin Route Scaffold

```typescript
// app/routes/app.[name].tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useNavigation, Form, useSubmit } from "react-router";
// ↑ ALWAYS from "react-router" — NEVER from "@remix-run/react"
import { useAppBridge } from "@shopify/app-bridge-react";
import { useEffect, useState, useCallback } from "react";
import {
  Page, Layout, Card, BlockStack, InlineStack, Text, Button,
  EmptyState, SkeletonPage, IndexTable, useIndexResourceState,
  Badge, Modal, Banner,
} from "@shopify/polaris";
import { authenticate } from "~/shopify.server";
import db from "~/db.server";

// ── Loader ────────────────────────────────────────────────────────────────────
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);  // LAW 1: FIRST

  try {
    const items = await db.quiz.findMany({
      where: { shop: session.shop },  // LAW 2: ALWAYS shop-scope
      select: { id: true, title: true, status: true, updatedAt: true },
      orderBy: { updatedAt: "desc" },
    });
    return json({ items });
  } catch (error) {
    throw json({ error: "Failed to load" }, { status: 500 });
  }
}

// ── Action ────────────────────────────────────────────────────────────────────
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);  // LAW 1: FIRST
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;  // LAW 2: get from session, NOT from client

  try {
    switch (intent) {
      case "delete": {
        const id = formData.get("id") as string;
        await db.quiz.deleteMany({ where: { id, shop } });  // deleteMany for safety
        return json({ success: true, message: "Deleted successfully" });
      }
      default:
        return json({ error: "Unknown intent" }, { status: 400 });
    }
  } catch (error) {
    return json(
      { error: error instanceof Error ? error.message : "Action failed" },
      { status: 500 }
    );
  }
}

// ── Component ─────────────────────────────────────────────────────────────────
export default function NewPage() {
  const { items } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const submit = useSubmit();
  const shopify = useAppBridge();    // App Bridge v4 toast
  const isLoading = navigation.state !== "idle";

  const [deleteTarget, setDeleteTarget] = useState<{ id: string; title: string } | null>(null);

  // LAW 8: Toast on every mutation
  useEffect(() => {
    if (actionData?.success) {
      shopify.toast.show(actionData.message ?? "Done", { duration: 3000 });
    }
    if (actionData?.error) {
      shopify.toast.show(actionData.error, { isError: true });
    }
  }, [actionData]);

  // LAW 10: Empty state for empty lists
  if (items.length === 0 && !isLoading) {
    return (
      <Page title="[Page Title]" primaryAction={{ content: "Create new", url: "/app/[name]/new" }}>
        <EmptyState
          heading="Create your first item"
          action={{ content: "Create", url: "/app/[name]/new" }}
          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
        >
          <p>Get started by creating your first item.</p>
        </EmptyState>
      </Page>
    );
  }

  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(items);

  return (
    <Page
      title="[Page Title]"
      primaryAction={{
        content: "Create new",
        url: "/app/[name]/new",
        loading: isLoading,
      }}
    >
      <Layout>
        <Layout.Section>
          <Card>
            <IndexTable
              resourceName={{ singular: "item", plural: "items" }}
              itemCount={items.length}
              selectedItemsCount={allResourcesSelected ? "All" : selectedResources.length}
              onSelectionChange={handleSelectionChange}
              loading={isLoading}
              headings={[
                { title: "Title" },
                { title: "Status" },
                { title: "Updated" },
                { title: "Actions" },
              ]}
            >
              {items.map((item, index) => (
                <IndexTable.Row
                  id={item.id}
                  key={item.id}
                  selected={selectedResources.includes(item.id)}
                  position={index}
                >
                  <IndexTable.Cell>
                    <Text as="span" fontWeight="semibold">{item.title}</Text>
                  </IndexTable.Cell>
                  <IndexTable.Cell>
                    <Badge tone={item.status === "active" ? "success" : "attention"}>
                      {item.status}
                    </Badge>
                  </IndexTable.Cell>
                  <IndexTable.Cell>
                    <Text as="span" tone="subdued">
                      {new Date(item.updatedAt).toLocaleDateString()}
                    </Text>
                  </IndexTable.Cell>
                  <IndexTable.Cell>
                    <InlineStack gap="200">
                      <Button url={`/app/[name]/${item.id}`} size="slim">Edit</Button>
                      <Button
                        size="slim"
                        tone="critical"
                        onClick={() => setDeleteTarget({ id: item.id, title: item.title })}
                      >
                        Delete
                      </Button>
                    </InlineStack>
                  </IndexTable.Cell>
                </IndexTable.Row>
              ))}
            </IndexTable>
          </Card>
        </Layout.Section>
      </Layout>

      {/* LAW 11: Banner confirmation for delete (preferred over Modal in embedded app) */}
      {deleteTarget && (
        <Banner
          tone="critical"
          title={`Delete "${deleteTarget.title}"?`}
          onDismiss={() => setDeleteTarget(null)}
        >
          <BlockStack gap="300">
