import db from "~/db.server";

// ── Loader ────────────────────────────────────────────────────────────────────
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);  // LAW 1: FIRST

  try {
    const items = await db.quiz.findMany({
      where: { shop: session.shop },  // LAW 2: ALWAYS shop-scope
      select: { id: true, title: true, status: true, updatedAt: true },
      orderBy: { updatedAt: "desc" },
    });
    return json({ items });
  } catch (error) {
    throw json({ error: "Failed to load" }, { status: 500 });
  }
}

// ── Action ────────────────────────────────────────────────────────────────────
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);  // LAW 1: FIRST
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;  // LAW 2: get from session, NOT from client

  try {
    switch (intent) {
      case "delete": {
        const id = formData.get("id") as string;
        await db.quiz.deleteMany({ where: { id, shop } });  // deleteMany for safety
        return json({ success: true, message: "Deleted successfully" });
      }
      default:
        return json({ error: "Unknown intent" }, { status: 400 });
    }
  } catch (error) {
    return json(
      { error: error instanceof Error ? error.message : "Action failed" },
      { status: 500 }
    );
  }
}

// ── Component ─────────────────────────────────────────────────────────────────
export default function NewPage() {
  const { items } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
