### Step 3: Install Template as Quiz (Transaction)

```typescript
// app/services/template.server.ts

export async function installTemplate(templateId: string, shop: string): Promise<string> {
  const template = await db.quizTemplate.findUnique({ where: { id: templateId } });
  if (!template) throw new Error("Template not found");

  const data = (() => {
    try { return JSON.parse(template.templateData) as TemplateData; }
    catch { throw new Error("Invalid template data"); }
  })();

  const slug = await generateUniqueSlug(template.name, shop);

  const quiz = await db.$transaction(async (tx) => {
    const newQuiz = await tx.quiz.create({
      data: {
        shop,
        title: template.name,
        slug,
        status: "draft",
        type: data.type,
        settings: JSON.stringify(data.settings),
        styling: JSON.stringify(data.styling),
      },
    });

    for (const q of data.questions) {
      const question = await tx.question.create({
        data: {
          quizId: newQuiz.id,
          type: q.type,
          title: q.title,
          description: q.description,
          required: q.required,
          position: q.position,
          settings: JSON.stringify(q.settings),
        },
      });

      for (const a of q.answers) {
        await tx.answer.create({
          data: {
            questionId: question.id,
            text: a.text,
            position: a.position,
            score: a.score,
            productTags: JSON.stringify(a.productTags),
          },
        });
      }
    }

    for (const rp of data.resultPages) {
      await tx.resultPage.create({
        data: {
          quizId: newQuiz.id,
          title: rp.title,
          description: rp.description,
          type: rp.type,
          minScore: rp.minScore,
          maxScore: rp.maxScore,
          matchTags: JSON.stringify(rp.matchTags),
          productLimit: rp.productLimit,
          layout: rp.layout,
          ctaText: rp.ctaText,
          position: rp.position,
        },
      });
    }

    // Increment usage count
    await tx.quizTemplate.update({
      where: { id: templateId },
      data: { usageCount: { increment: 1 } },
    });

    return newQuiz;
  });

  return quiz.id;
}
```

