### Step 2: A/B Test Service (`app/services/ab-test.server.ts`)

```typescript
import db from "~/db.server";

interface ABTestVariant {
  id: string;
  name: string;
  quizId: string;
  description: string;
}

interface ABTestTrafficSplit {
  [variantId: string]: number;  // Must sum to 100
}

export async function createABTest(shop: string, data: {
  quizId: string;
  name: string;
  controlQuizId: string;    // variant A — original quiz
  treatmentQuizId: string;  // variant B — variation quiz
  trafficSplit?: number;    // % to variant B, default 50
}): Promise<string> {
  const quiz = await db.quiz.findFirst({ where: { id: data.quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  const split = data.trafficSplit ?? 50;
  const variants: ABTestVariant[] = [
    { id: "control", name: "Control", quizId: data.controlQuizId, description: "Original quiz" },
    { id: "treatment", name: "Treatment", quizId: data.treatmentQuizId, description: "Variation" },
  ];
  const trafficSplit: ABTestTrafficSplit = {
    control: 100 - split,
    treatment: split,
  };

  const test = await db.aBTest.create({
    data: {
      shop,
      quizId: data.quizId,
      name: data.name,
      status: "draft",
      variants: JSON.stringify(variants),
      trafficSplit: JSON.stringify(trafficSplit),
    },
  });

  return test.id;
}

export async function getABTestMetrics(testId: string, shop: string) {
  const test = await db.aBTest.findFirst({
    where: { id: testId, shop },  // ALWAYS shop-scope
  });
  if (!test) throw new Error("Test not found");

  const variants = (() => {
    try { return JSON.parse(test.variants) as ABTestVariant[]; }
    catch { return []; }
  })();

  // Get metrics per variant from analytics events
  // Variant info stored in AnalyticsEvent.data JSON field
  const metricsByVariant: Record<string, {
    starts: number; completions: number; conversions: number;
  }> = {};

  for (const variant of variants) {
    const [starts, completions, conversions] = await Promise.all([
      db.analyticsEvent.count({
        where: { shop, quizId: variant.quizId, eventType: "quiz_started" },
      }),
      db.analyticsEvent.count({
        where: { shop, quizId: variant.quizId, eventType: "quiz_completed" },
      }),
      db.analyticsEvent.count({
        where: { shop, quizId: variant.quizId, eventType: "added_to_cart" },
      }),
    ]);

    metricsByVariant[variant.id] = { starts, completions, conversions };
  }

  return { test, variants, metrics: metricsByVariant };
}
```

### Step 3: Traffic Splitting (Widget Side)

```javascript
// In quiz-widget.js — called when widget initializes
async function getVariant(testId, shop) {
  const cookieKey = `qs_ab_${testId}`;
  const existing = getCookie(cookieKey);
  if (existing) return existing;

  // Fetch assignment from server
  const res = await fetch(`/api/ab-test/${testId}/assign?shop=${shop}`);
  const { variantId } = await res.json();

  // Sticky assignment — 30 day cookie
  setCookie(cookieKey, variantId, 30);
  return variantId;
}
```

