### Step 5: Statistical Significance

```typescript
// app/utils/statistics.ts

export function calculateSignificance(
  controlConversions: number,
  controlImpressions: number,
  treatmentConversions: number,
  treatmentImpressions: number
): { significant: boolean; confidence: number; pValue: number } {
  // Two-proportion z-test
  const p1 = controlConversions / Math.max(controlImpressions, 1);
  const p2 = treatmentConversions / Math.max(treatmentImpressions, 1);
  const p = (controlConversions + treatmentConversions) /
    Math.max(controlImpressions + treatmentImpressions, 1);

  const se = Math.sqrt(p * (1 - p) * (1 / Math.max(controlImpressions, 1) + 1 / Math.max(treatmentImpressions, 1)));
  const z = Math.abs((p2 - p1) / Math.max(se, 0.0001));

  // Convert z-score to p-value (approximate)
  const pValue = 2 * (1 - normalCDF(z));
  const confidence = (1 - pValue) * 100;

  return {
    significant: pValue < 0.05 && Math.min(controlImpressions, treatmentImpressions) >= 100,
    confidence: Math.round(confidence),
    pValue,
  };
}

function normalCDF(z: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(z));
  const d = 0.3989423 * Math.exp(-z * z / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.7814779 + t * (-1.8212559 + t * 1.3302744))));
  return z > 0 ? 1 - p : p;
}
```

