# Shopify Customer Tags Agent — Post-Quiz Customer Segmentation

You implement Shopify customer tagging and metafield updates triggered by quiz completion. This enables merchants to segment their customers based on quiz outcomes and preferences.

---

## AUTO-DETECT TRIGGERS

- "apply customer tags", "tag customer after quiz"
- "customer segmentation", "quiz result customer tag"
- "customer metafield", "store quiz results on customer"
- "Shopify Flow trigger", "customer profile enrichment"

---

## DECISION TREE

```
Customer tagging needed
├── Quiz completed with email captured?
│   ├── YES → look up Shopify customer by email
│   │   ├── Customer found → apply tags + update metafields
│   │   └── Customer not found → skip gracefully (no error)
│   └── NO → cannot tag (no customer identity)
├── Build tag list from quiz result:
│   ├── Result profile name tag: "quiz-result:[result-page-slug]"
│   ├── Quiz completion tag: "quiz-completed:[quiz-slug]"
│   └── Answer-based tags from Answer.productTags
├── Apply tags via Admin GraphQL API
└── Update customer metafields with quiz data
```

---

## IMPLEMENTATION

### Service File

```typescript
// app/services/customer-tags.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-react-router";
import db from "~/db.server";

interface QuizCompletionData {
  email: string;
  quizId: string;
  quizSlug: string;
  resultPageId: string;
  resultPageTitle: string;
  score: number;
  answers: Array<{ questionId: string; answerId?: string; value?: string }>;
  productTags: string[];
}

// Shopify GraphQL mutation to apply customer tags
const APPLY_CUSTOMER_TAGS_MUTATION = `#graphql
  mutation customerTagsAdd($id: ID!, $tags: [String!]!) {
    tagsAdd(id: $id, tags: $tags) {
      node {
        id
      }
      userErrors {
        field
        message
      }
    }
  }
` as const;

const CUSTOMER_BY_EMAIL_QUERY = `#graphql
  query GetCustomerByEmail($email: String!) {
    customers(first: 1, query: $email) {
      nodes {
        id
        email
        tags
      }
    }
  }
` as const;

const SET_CUSTOMER_METAFIELD_MUTATION = `#graphql
  mutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {
    metafieldsSet(metafields: $metafields) {
      metafields {
        key
        namespace
        value
      }
      userErrors {
        field
        message
      }
    }
  }
` as const;

export async function applyQuizTagsToCustomer(
  admin: AdminApiContext,
  data: QuizCompletionData
): Promise<void> {
  try {
    // 1. Find customer by email
    const customerResponse = await admin.graphql(CUSTOMER_BY_EMAIL_QUERY, {
      variables: { email: `email:${data.email}` },
    });
    const customers = customerResponse.data?.customers?.nodes ?? [];

    if (customers.length === 0) {
      // Customer not registered — skip gracefully
      console.info(`No Shopify customer found for ${data.email} — skipping tags`);
      return;
    }

    const customer = customers[0];
    const customerId = customer.id;

    // 2. Build tag list
    const newTags = [
      `quiz-completed:${data.quizSlug}`,
      `quiz-result:${data.resultPageTitle.toLowerCase().replace(/\s+/g, "-")}`,
      ...data.productTags.map((tag) => `pref:${tag}`),
    ];

    // 3. Apply tags (Shopify auto-deduplicates)
    const tagResponse = await admin.graphql(APPLY_CUSTOMER_TAGS_MUTATION, {
      variables: { id: customerId, tags: newTags },
    });

    if (tagResponse.data?.tagsAdd?.userErrors?.length > 0) {
      console.error("Customer tag errors:", tagResponse.data.tagsAdd.userErrors);
    }

    // 4. Update customer metafields with quiz data
    const metafieldResponse = await admin.graphql(SET_CUSTOMER_METAFIELD_MUTATION, {
      variables: {
        metafields: [
          {
            ownerId: customerId,
            namespace: "quizsnap",
            key: "last_quiz_result",
            value: JSON.stringify({
              quizId: data.quizId,
              quizSlug: data.quizSlug,
              resultPageId: data.resultPageId,
              resultPageTitle: data.resultPageTitle,
              score: data.score,
              completedAt: new Date().toISOString(),
            }),
            type: "json",
          },
          {
            ownerId: customerId,
            namespace: "quizsnap",
            key: "product_preferences",
            value: JSON.stringify(data.productTags),
            type: "json",
          },
        ],
      },
    });

    if (metafieldResponse.data?.metafieldsSet?.userErrors?.length > 0) {
      console.error("Metafield errors:", metafieldResponse.data.metafieldsSet.userErrors);
    }

  } catch (error) {
    // NEVER let customer tagging failure break quiz submission
    console.error("Customer tagging failed:", error);
  }
}
```

### Wire Up in Quiz Submission

```typescript
