// app/services/ab-test.server.ts
import db from "~/db.server";

interface ABTestVariant {
  id: string;
  name: string;
  quizId: string;
  description: string;
}

export async function createABTest(shop: string, data: {
  baseQuizId: string;
  name: string;
  treatmentQuizId: string;
  trafficSplit?: number;
}) {
  // Verify ownership of both quizzes
  const [baseQuiz, treatmentQuiz] = await Promise.all([
    db.quiz.findFirst({ where: { id: data.baseQuizId, shop } }),
    db.quiz.findFirst({ where: { id: data.treatmentQuizId, shop } }),
  ]);

  if (!baseQuiz || !treatmentQuiz) throw new Error("Quiz not found or access denied");

  const split = data.trafficSplit ?? 50;
  const variants: ABTestVariant[] = [
    { id: "control", name: "Control", quizId: data.baseQuizId, description: "Original quiz" },
    { id: "treatment", name: "Treatment", quizId: data.treatmentQuizId, description: "Variation" },
  ];

  return db.aBTest.create({
    data: {
      shop,
      quizId: data.baseQuizId,
      name: data.name,
      status: "draft",
      variants: JSON.stringify(variants),
      trafficSplit: JSON.stringify({ control: 100 - split, treatment: split }),
    },
  });
}

export async function startABTest(testId: string, shop: string) {
  const test = await db.aBTest.findFirst({ where: { id: testId, shop } });
  if (!test) throw new Error("Test not found");
  if (test.status !== "draft") throw new Error("Can only start draft tests");

  return db.aBTest.update({
    where: { id: testId },
    data: { status: "running", startedAt: new Date() },
  });
}

export async function getABTestMetrics(testId: string, shop: string) {
  const test = await db.aBTest.findFirst({
    where: { id: testId, shop },
  });
  if (!test) throw new Error("Test not found");

  const variants = parseSafe<ABTestVariant[]>(test.variants, []);

  const metrics = await Promise.all(
    variants.map(async (variant) => {
      const [starts, completions, conversions] = await Promise.all([
        db.analyticsEvent.count({
          where: { shop, quizId: variant.quizId, eventType: "quiz_started" },
        }),
        db.analyticsEvent.count({
          where: { shop, quizId: variant.quizId, eventType: "quiz_completed" },
        }),
        db.analyticsEvent.count({
          where: { shop, quizId: variant.quizId, eventType: "added_to_cart" },
        }),
      ]);

      return {
        variantId: variant.id,
        variantName: variant.name,
        starts,
        completions,
        conversions,
        completionRate: starts > 0 ? Math.round((completions / starts) * 100 * 10) / 10 : 0,
        conversionRate: completions > 0 ? Math.round((conversions / completions) * 100 * 10) / 10 : 0,
      };
    })
  );

  return { test, variants, metrics };
}

export async function declareWinner(testId: string, shop: string, winnerVariantId: string) {
  const test = await db.aBTest.findFirst({ where: { id: testId, shop } });
  if (!test) throw new Error("Test not found");

  return db.aBTest.update({
    where: { id: testId },
    data: {
      status: "completed",
      winnerVariant: winnerVariantId,
      endedAt: new Date(),
    },
  });
}

function parseSafe<T>(str: string, fallback: T): T {
