## STATISTICAL SIGNIFICANCE

```typescript
// app/utils/statistics.ts
export function calculateSignificance(
  controlConversions: number,
  controlStarts: number,
  treatmentConversions: number,
  treatmentStarts: number
): { significant: boolean; confidence: number; improvementPct: number } {

  const minSample = Math.min(controlStarts, treatmentStarts);
  if (minSample < 100) {
    return { significant: false, confidence: 0, improvementPct: 0 };
  }

  const p1 = controlConversions / Math.max(controlStarts, 1);
  const p2 = treatmentConversions / Math.max(treatmentStarts, 1);
  const p = (controlConversions + treatmentConversions) /
    Math.max(controlStarts + treatmentStarts, 1);

  const se = Math.sqrt(p * (1 - p) * (1 / Math.max(controlStarts, 1) + 1 / Math.max(treatmentStarts, 1)));
  if (se === 0) return { significant: false, confidence: 0, improvementPct: 0 };

  const z = Math.abs((p2 - p1) / se);
  const pValue = 2 * (1 - normalCDF(z));
  const confidence = Math.round((1 - pValue) * 100);
  const improvementPct = p1 > 0 ? Math.round(((p2 - p1) / p1) * 100 * 10) / 10 : 0;

  return {
    significant: pValue < 0.05,  // 95% confidence threshold
    confidence,
    improvementPct,
  };
}

function normalCDF(z: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(z));
  const d = 0.3989423 * Math.exp(-z * z / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.7814779 + t * (-1.8212559 + t * 1.3302744))));
  return z > 0 ? 1 - p : p;
}
```

