async function getVariantQuizId(testId, shop) {
  const cookieKey = `qs_ab_${testId}`;

  // Check for sticky assignment (30 days)
  const existing = getCookie(cookieKey);
  if (existing) return existing;

  // Get assignment from server
  try {
    const res = await fetch(`/api/ab-test/${testId}/assign?shop=${encodeURIComponent(shop)}`);
    if (!res.ok) return null;  // Fall back to control quiz
    const { quizId } = await res.json();
    setCookie(cookieKey, quizId, 30);
    return quizId;
  } catch {
    return null;  // Fall back to control quiz on any error
  }
}

function getCookie(name) {
  return document.cookie.split("; ").find((row) => row.startsWith(`${name}=`))?.split("=")[1] ?? null;
}

function setCookie(name, value, days) {
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  document.cookie = `${name}=${value}; expires=${expires}; path=/; SameSite=Lax`;
}
