```typescript
// app/services/export.server.ts
import db from "~/db.server";

// ── Quiz Responses CSV ────────────────────────────────────────────────────────
export async function exportQuizResponses(
  shop: string,
  quizId: string,
  dateRange?: { from: Date; to: Date }
): Promise<string> {
  const quiz = await db.quiz.findFirst({
    where: { id: quizId, shop },  // ALWAYS ownership check
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
    },
  });
  if (!quiz) throw new Error("Quiz not found");

  const responses = await db.quizResponse.findMany({
    where: {
      shop,  // NOT shopId
      quizId,
      ...(dateRange ? { createdAt: { gte: dateRange.from, lte: dateRange.to } } : {}),
    },
    orderBy: { createdAt: "desc" },
  });

  const headers = [
    "Response ID", "Email", "Score", "Completed At", "Source", "Device",
    ...quiz.questions.map((q) => csvEscape(`Q: ${q.title}`)),
  ];

  const rows = responses.map((r) => {
    const parsedAnswers = parseSafe<Array<{ questionId: string; answerId?: string; value?: string }>>(r.answers, []);
    const answerMap: Record<string, string> = {};

    for (const a of parsedAnswers) {
      const question = quiz.questions.find((q) => q.id === a.questionId);
      const answer = question?.answers.find((ans) => ans.id === a.answerId);
      answerMap[a.questionId] = answer?.text ?? a.value ?? "";
    }

    return [
      r.id,
      r.email ?? "",
      String(r.score),
      r.completedAt ? new Date(r.completedAt).toISOString() : "",
      r.source,
      r.deviceType ?? "",
      ...quiz.questions.map((q) => csvEscape(answerMap[q.id] ?? "")),
    ];
  });

  return [headers.join(","), ...rows.map((row) => row.join(","))].join("\n");
}

// ── Quiz Configuration JSON ───────────────────────────────────────────────────
export async function exportQuizConfig(quizId: string, shop: string): Promise<string> {
  const quiz = await db.quiz.findFirst({
    where: { id: quizId, shop },
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
    },
  });
  if (!quiz) throw new Error("Quiz not found");

  // Strip shop-specific fields for portability
  const exportData = {
    version: "1.0",
    exportedAt: new Date().toISOString(),
    quiz: {
      title: quiz.title,
      description: quiz.description,
      type: quiz.type,
      settings: parseSafe(quiz.settings, {}),
      styling: parseSafe(quiz.styling, {}),
      questions: quiz.questions.map((q) => ({
        type: q.type,
        title: q.title,
        description: q.description,
        required: q.required,
        position: q.position,
        settings: parseSafe(q.settings, {}),
        logic: parseSafe(q.logic, {}),
        answers: q.answers.map((a) => ({
          text: a.text,
          position: a.position,
          score: a.score,
          productTags: parseSafe(a.productTags, [] as string[]),
        })),
      })),
      resultPages: quiz.resultPages.map((rp) => ({
        title: rp.title,
        description: rp.description,
        type: rp.type,
        minScore: rp.minScore,
        maxScore: rp.maxScore,
        matchTags: parseSafe(rp.matchTags, [] as string[]),
        productLimit: rp.productLimit,
        layout: rp.layout,
        ctaText: rp.ctaText,
        position: rp.position,
      })),
    },
  };

  return JSON.stringify(exportData, null, 2);
}

// ── Analytics Summary CSV ─────────────────────────────────────────────────────
export async function exportAnalyticsSummary(
  shop: string,
  quizId: string,
  days: number = 30
): Promise<string> {
  const from = new Date(Date.now() - days * 86400000);

  const events = await db.analyticsEvent.findMany({
    where: { shop, quizId, createdAt: { gte: from } },
    select: { eventType: true, revenue: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });

  // Group by date
  const byDate: Record<string, { starts: number; completions: number; conversions: number; revenue: number }> = {};

  for (const event of events) {
    const date = event.createdAt.toISOString().slice(0, 10);
    if (!byDate[date]) byDate[date] = { starts: 0, completions: 0, conversions: 0, revenue: 0 };

    if (event.eventType === "quiz_started") byDate[date].starts++;
    if (event.eventType === "quiz_completed") byDate[date].completions++;
    if (event.eventType === "added_to_cart") byDate[date].conversions++;
    if (event.eventType === "purchase") byDate[date].revenue += event.revenue;
  }

  const headers = ["Date", "Starts", "Completions", "Completion Rate", "Conversions", "Revenue"];
  const rows = Object.entries(byDate).map(([date, metrics]) => [
    date,
    metrics.starts,
    metrics.completions,
    metrics.starts > 0 ? `${((metrics.completions / metrics.starts) * 100).toFixed(1)}%` : "0%",
    metrics.conversions,
    `$${metrics.revenue.toFixed(2)}`,
  ]);

  return [headers.join(","), ...rows.map((row) => row.join(","))].join("\n");
}

// ── Helpers ───────────────────────────────────────────────────────────────────
function csvEscape(value: string): string {
  if (value.includes(",") || value.includes("\n") || value.includes('"')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

function parseSafe<T>(str: string, fallback: T): T {
  try { return JSON.parse(str) as T; } catch { return fallback; }
}
