// Server validation + client display pattern:
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const title = (formData.get("title") as string ?? "").trim();
  const slug = (formData.get("slug") as string ?? "").trim();

  const errors: Record<string, string> = {};
  if (!title) errors.title = "Title is required";
  if (title.length > 120) errors.title = "Title must be 120 characters or less";
  if (!slug) errors.slug = "Slug is required";
  if (!/^[a-z0-9-]+$/.test(slug)) errors.slug = "Slug can only contain lowercase letters, numbers, and hyphens";

  if (Object.keys(errors).length > 0) {
    return json({ errors }, { status: 400 });
  }

  // ... proceed with save
}

// In component — show inline errors:
const actionData = useActionData<typeof action>();
const errors = actionData?.errors ?? {};

<TextField
  label="Title"
  name="title"
  value={title}
  onChange={setTitle}
  error={errors.title}  // Inline error below field
  autoComplete="off"
/>
```

