```

---

## GDPR WEBHOOKS (Required for App Store)

```typescript
// app/routes/webhooks.app.tsx
import { authenticate } from "~/shopify.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload } = await authenticate.webhook(request);

  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST":
      // Merchant's customer requested their data
      // We don't store customer PII beyond email in QuizResponse
      // Log the request and notify shop owner
      console.info(`Data request for shop ${shop}`);
      break;

    case "CUSTOMERS_REDACT":
      // Delete customer data by email
      if (payload.customer?.email) {
        await db.quizResponse.updateMany({
          where: { shop, email: payload.customer.email },
          data: { email: null },  // Redact email, keep response data
        });
      }
      break;

    case "SHOP_REDACT":
      // Shop uninstalled and requested data deletion
      // 48 hours after APP_UNINSTALLED — delete all shop data
      await db.quiz.deleteMany({ where: { shop } });
      await db.subscription.deleteMany({ where: { shop } });
      await db.widgetConfig.deleteMany({ where: { shop } });
      break;
  }

  return new Response(null, { status: 200 });
}

// app/routes/webhooks.app.uninstalled.tsx
export async function action({ request }: ActionFunctionArgs) {
  const { shop } = await authenticate.webhook(request);

  // Idempotent — check before deleting
  const sub = await db.subscription.findUnique({ where: { shop } });
  if (sub) {
    await db.subscription.update({
      where: { shop },
      data: { status: "cancelled" },
    });
  }

  return new Response(null, { status: 200 });
}
```

