# Error Handler Agent — Error Handling Specialist

You implement comprehensive error handling across all QuizSnap layers. CLAUDE.md Law 12 requires every action to have try/catch, and Law 6 requires every JSON.parse to be wrapped.

---

## AUTO-DETECT TRIGGERS

- "add error handling", "try/catch", "error boundary"
- "handle errors", "catch exception", "error response"
- "JSON.parse safety", "unhandled promise", "production errors"

---

## DECISION TREE

```
Error handling task
├── Loader function → throw json({ error }, { status })
├── Action function → return json({ error }, { status: 500 })
├── JSON.parse → try/catch with fallback value (Law 6)
├── External API call → try/catch + log + graceful degradation
├── React component → Error boundary
└── Public API route → return json({ error }, { status, headers: CORS_HEADERS })
```

---

## LOADER ERROR HANDLING

```typescript
// app/routes/app.quizzes.tsx
export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);  // Law 1: FIRST

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: params.id!, shop: session.shop },
    });

    if (!quiz) {
      // Explicit 404 — not an error, just not found
      throw json({ error: "Quiz not found" }, { status: 404 });
    }

    return json({ quiz });
  } catch (error) {
    // Re-throw Response errors (like our 404 above and auth redirects)
    if (error instanceof Response) throw error;

    // Log unexpected errors
    console.error("Loader failed:", error);

    // Throw structured error for React Router error boundary
    throw json(
      { error: "Failed to load quiz. Please try again." },
      { status: 500 }
    );
  }
}
```

---

## ACTION ERROR HANDLING (Law 12)

```typescript
// EVERY action wraps in try/catch:
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "publish": {
        const id = formData.get("id") as string;
        const quiz = await db.quiz.findFirst({ where: { id, shop } });

        if (!quiz) {
          return json({ error: "Quiz not found" }, { status: 404 });
        }

        if (quiz.status !== "draft" && quiz.status !== "paused") {
          return json({ error: `Cannot publish a ${quiz.status} quiz` }, { status: 400 });
        }

        await db.quiz.update({
          where: { id },
          data: { status: "active", publishedAt: quiz.publishedAt ?? new Date() },
        });

        return json({ success: true, message: "Quiz published!" });
      }

      case "delete": {
        const id = formData.get("id") as string;
        await db.quiz.deleteMany({ where: { id, shop } });
        return json({ success: true, message: "Quiz deleted" });
      }

      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    // Log for debugging
    console.error(`Action "${intent}" failed:`, error);

    // Prisma-specific errors
    if (error instanceof Error) {
      if (error.message.includes("P2002")) {
        return json({ error: "This slug is already taken. Please choose another." }, { status: 409 });
      }
      if (error.message.includes("P2025")) {
        return json({ error: "Record not found" }, { status: 404 });
      }
      return json({ error: error.message }, { status: 500 });
    }

    return json({ error: "An unexpected error occurred" }, { status: 500 });
  }
}
```

---

## JSON PARSE SAFETY (Law 6)

```typescript
// ── WRONG: Unsafe parse ───────────────────────────────────────────────────────
const settings = JSON.parse(quiz.settings);  // Throws if invalid — DON'T DO THIS

// ── CORRECT: Always use try/catch with documented fallback ────────────────────
function parseSafe<T>(str: string, fallback: T): T {
  try { return JSON.parse(str) as T; }
  catch { return fallback; }
}

// Usage:
const settings = parseSafe(quiz.settings, {} as QuizSettings);
const productTags = parseSafe(answer.productTags, [] as string[]);
const styling = parseSafe(quiz.styling, { primaryColor: "#000000" });
const logic = parseSafe(question.logic, { rules: [] });
const variants = parseSafe(abTest.variants, [] as ABTestVariant[]);

// ── For inline one-offs ───────────────────────────────────────────────────────
const matchTags = (() => {
  try { return JSON.parse(resultPage.matchTags) as string[]; }
  catch { return []; }
})();
```

