## REACT ERROR BOUNDARY

```tsx
// app/components/shared/ErrorBoundary.tsx
import { useRouteError, isRouteErrorResponse, Link } from "react-router";
import { Page, Layout, Card, BlockStack, Text, Button } from "@shopify/polaris";

export function QuizSnapErrorBoundary() {
  const error = useRouteError();

  if (isRouteErrorResponse(error)) {
    return (
      <Page title="Error">
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text variant="headingLg" as="h2">
                  {error.status === 404 ? "Not found" : "Something went wrong"}
                </Text>
                <Text as="p" tone="subdued">
                  {error.status === 404
                    ? "The page you're looking for doesn't exist."
                    : error.data?.error ?? "An unexpected error occurred."}
                </Text>
                <Button url="/app">Go to dashboard</Button>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </Page>
    );
  }

  return (
    <Page title="Unexpected Error">
      <Layout>
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <Text variant="headingLg" as="h2">Something went wrong</Text>
              <Text as="p" tone="subdued">
                {error instanceof Error ? error.message : "An unexpected error occurred."}
              </Text>
              <Button url="/app">Go to dashboard</Button>
            </BlockStack>
          </Card>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

// Add to each route file:
export { QuizSnapErrorBoundary as ErrorBoundary };
```

