```typescript
// app/routes/api.quiz.$slug.tsx
import { CORS_HEADERS } from "~/utils/cors";

export async function loader({ request, params }: LoaderFunctionArgs) {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  try {
    const { slug } = params;
    const shop = new URL(request.url).searchParams.get("shop");

    if (!slug || !shop) {
      return json(
        { error: "Missing slug or shop" },
        { status: 400, headers: CORS_HEADERS }  // CORS on error responses too!
      );
    }

    const quiz = await db.quiz.findUnique({
      where: { shop_slug: { shop, slug } },
    });

    if (!quiz || quiz.status !== "active") {
      return json(
        { error: "Quiz not found" },
        { status: 404, headers: CORS_HEADERS }
      );
    }

    return json({ quiz: formatQuiz(quiz) }, { headers: CORS_HEADERS });

  } catch (error) {
    console.error("Public API error:", error);
    return json(
      { error: "Internal server error" },
      { status: 500, headers: CORS_HEADERS }  // CORS on 500 too!
    );
  }
}
