## MAILCHIMP API PATTERNS

```typescript
// app/services/mailchimp.server.ts
import crypto from "crypto";
import db from "~/db.server";

interface MailchimpSettings {
  audienceId: string;
  serverPrefix: string;  // e.g., "us1", "us14"
  tagPrefix?: string;    // prefix for quiz tags, default "quiz"
  mergeFields?: {
    quizResult?: string;  // MERGE field name, e.g., "QUIZRESULT"
    quizScore?: string;   // e.g., "QUIZSCORE"
  };
}

export async function syncToMailchimp(
  apiKey: string,
  settings: MailchimpSettings,
  email: string,
  quizData: {
    quizTitle: string;
    quizSlug: string;
    resultPageTitle: string;
    score: number;
    productTags: string[];
  }
): Promise<void> {
  const { audienceId, serverPrefix } = settings;

  // Mailchimp uses MD5 hash of lowercase email for member ID
  const emailHash = crypto.createHash("md5").update(email.toLowerCase()).digest("hex");

  const memberData = {
    email_address: email,
    status_if_new: "subscribed",  // Don't resubscribe if unsubscribed
    merge_fields: {
      ...(settings.mergeFields?.quizResult ? {
        [settings.mergeFields.quizResult]: quizData.resultPageTitle,
      } : {}),
      ...(settings.mergeFields?.quizScore ? {
        [settings.mergeFields.quizScore]: String(quizData.score),
      } : {}),
    },
    tags: [
      `${settings.tagPrefix ?? "quiz"}-${quizData.quizSlug}`,
      `result-${quizData.resultPageTitle.toLowerCase().replace(/\s+/g, "-")}`,
      ...quizData.productTags.map((tag) => `pref-${tag}`),
    ],
  };

  // Use PUT to upsert (add or update) subscriber
  const response = await fetch(
    `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${audienceId}/members/${emailHash}`,
    {
      method: "PUT",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(memberData),
    }
  );

  if (!response.ok) {
    const error = await response.json().catch(() => ({ detail: response.statusText }));
    throw new Error(`Mailchimp API error: ${error.detail ?? response.status}`);
  }
}

// ── Connection test ────────────────────────────────────────────────────────────
export async function testMailchimpConnection(
  apiKey: string,
  serverPrefix: string
): Promise<{ success: boolean; accountName?: string; error?: string }> {
  try {
    const response = await fetch(
      `https://${serverPrefix}.api.mailchimp.com/3.0/`,
      {
        headers: { "Authorization": `Bearer ${apiKey}` },
      }
    );

    if (!response.ok) {
      return { success: false, error: `Invalid API key or server prefix` };
    }

    const data = await response.json();
    return { success: true, accountName: data.account_name };
  } catch {
    return { success: false, error: "Cannot connect to Mailchimp" };
  }
}

// ── Get audiences list ─────────────────────────────────────────────────────────
export async function getMailchimpAudiences(
  apiKey: string,
  serverPrefix: string
): Promise<Array<{ id: string; name: string; memberCount: number }>> {
  const response = await fetch(
    `https://${serverPrefix}.api.mailchimp.com/3.0/lists?count=100&fields=lists.id,lists.name,lists.stats.member_count`,
    { headers: { "Authorization": `Bearer ${apiKey}` } }
  );

  if (!response.ok) throw new Error("Failed to fetch Mailchimp audiences");

  const data = await response.json();
  return (data.lists ?? []).map((list: { id: string; name: string; stats?: { member_count?: number } }) => ({
    id: list.id,
    name: list.name,
    memberCount: list.stats?.member_count ?? 0,
  }));
}
```

